package com.apiautomation.database;
import com.apiautomation.base.TestConfig;import java.sql.*;
public class DatabaseHelper {private Connection connect()throws SQLException{return DriverManager.getConnection(TestConfig.dbUrl(),TestConfig.dbUser(),TestConfig.dbPassword());}public Row find(String email)throws SQLException{try(var c=connect();var p=c.prepareStatement("select id,name,email,password,role from users where email=?")){p.setString(1,email);try(var r=p.executeQuery()){return r.next()?new Row(r.getLong("id"),r.getString("name"),r.getString("email"),r.getString("password"),r.getString("role")):null;}}}public boolean exists(long id)throws SQLException{try(var c=connect();var p=c.prepareStatement("select 1 from users where id=?")){p.setLong(1,id);try(var r=p.executeQuery()){return r.next();}}}public void cleanup(String email)throws SQLException{try(var c=connect();var p=c.prepareStatement("delete from users where email=?")){p.setString(1,email);p.executeUpdate();}}public record Row(long id,String name,String email,String password,String role){} }
